String _go_router() => r'''
// The GoRouter tab: the app's route tree, its location and match stack, recent locations and a box that calls go.

const HISTORY = 50;

const style = (el, css) => Object.assign(el.style, css);

function h(tag, text, css) {
  const el = document.createElement(tag);
  if (text !== undefined) el.textContent = text;
  if (css) style(el, css);
  return el;
}

function button(text, onclick, css) {
  const b = h('button', text, css);
  b.type = 'button';
  b.onclick = onclick;
  return b;
}

const mono = (text, css) => h('span', text, { fontFamily: 'var(--mono)', ...css });

function muted(text, tag = 'span', css) {
  const el = h(tag, text, css);
  el.className = 'muted';
  return el;
}

function query(location) {
  const params = {};
  for (const [key, value] of new URL(location, 'http://app').searchParams) {
    params[key] = key in params ? [params[key], value].flat() : value;
  }
  return params;
}

export default {
  api: 1,
  id: 'go_router',
  label: 'GoRouter',
  kinds: ['go_router.location'],
  renderTab(el, context) {
    let alive = true;
    let routes = null;
    let current = null;
    let run = null;
    // Newest last; one run only, as a restart starts the router over.
    let history = [];
    // The box follows the app's location until the user types in it.
    let edited = false;

    style(el, { display: 'flex', gap: '24px', alignItems: 'flex-start', flexWrap: 'wrap' });
    const side = h('div', undefined, { flex: '1 1 260px', minWidth: '0' });
    const main = h('div', undefined, { flex: '2 1 360px', minWidth: '0' });
    el.append(main, side);

    const input = h('input', undefined, { flex: '1', minWidth: '0', fontFamily: 'var(--mono)' });
    input.placeholder = '/location?query';
    input.spellcheck = false;
    input.oninput = () => {
      edited = input.value !== (current?.location ?? '');
    };
    input.onkeydown = (e) => {
      if (e.key === 'Enter') go();
    };
    const goButton = button('Go', () => go());
    const bar = h('div', undefined, { display: 'flex', gap: '8px', alignItems: 'center' });
    bar.append(input, goButton);
    const note = h('p');
    note.className = 'muted';
    const now = h('div');
    const recent = h('div');
    main.append(bar, note, now, recent);

    const tree = h('div');
    const routesHead = h('div', undefined, { display: 'flex', alignItems: 'center', gap: '8px' });
    routesHead.append(
      h('h3', 'Routes', { flex: '1' }),
      button('Refresh', () => load()),
    );
    side.append(routesHead, tree);

    const fail = (err) => {
      const message = err instanceof Error ? err.message : String(err);
      return message.includes('No handler named go_router.')
        ? 'The app has not called DevpulGoRouter.attach(router).'
        : message;
    };

    const fill = (location) => {
      input.value = location;
      edited = location !== (current?.location ?? '');
      input.focus();
    };

    const go = async () => {
      const location = input.value.trim();
      if (!location) return;
      goButton.disabled = true;
      try {
        await context.request('go_router.go', { location });
        if (!alive) return;
        note.textContent = '';
        edited = false;
      } catch (err) {
        if (alive) note.textContent = fail(err);
      }
      goButton.disabled = false;
    };

    const drawCurrent = () => {
      now.replaceChildren();
      if (!edited) input.value = current?.location ?? '';
      if (!current) {
        now.append(h('p', routes ? 'No location yet.' : '', { margin: '12px 0' }));
        return;
      }
      const head = h('div', undefined, { display: 'flex', alignItems: 'center', gap: '8px' });
      head.append(h('h3', 'Location', { flex: '1' }), context.ui.copy(current.location, 'Copy'));
      const location = h('pre', current.location);
      location.className = 'code';
      now.append(head, location);
      if (current.error) now.append(h('p', current.error, { color: 'var(--destructive)' }));

      if (current.matches.length) {
        now.append(h('h3', 'Matches'));
        const list = h('ol', undefined, { listStyle: 'none', margin: '0', padding: '0' });
        for (const m of current.matches) {
          const li = h('li', undefined, {
            padding: '3px 0',
            paddingLeft: `${m.depth * 16}px`,
            display: 'flex',
            gap: '8px',
            flexWrap: 'wrap',
            alignItems: 'baseline',
          });
          if (m.shell) {
            li.append(muted(m.branch === undefined ? m.shell : `${m.shell}, branch ${m.branch}`));
          } else {
            li.append(mono(m.location, { fontWeight: '500' }));
            if (m.path !== m.location) li.append(mono(m.path, { opacity: '0.7' }));
            if (m.name) li.append(muted(m.name));
            if (m.pushed) li.append(muted('pushed'));
          }
          list.append(li);
        }
        now.append(list);
      }

      const params = { ...current.pathParameters };
      const search = query(current.location);
      if (Object.keys(params).length) now.append(h('h3', 'Path parameters'), context.ui.keyValues(params));
      if (Object.keys(search).length) now.append(h('h3', 'Query parameters'), context.ui.keyValues(search));
      if ('extra' in current) now.append(h('h3', 'Extra'), context.ui.json(current.extra));
    };

    const drawHistory = () => {
      recent.replaceChildren();
      if (history.length < 2) return;
      recent.append(h('h3', 'Recent'));
      const list = h('ol', undefined, { listStyle: 'none', margin: '0', padding: '0' });
      for (const e of history.toReversed().slice(1)) {
        const li = h('li', undefined, { display: 'flex', gap: '8px', alignItems: 'baseline', padding: '2px 0' });
        const at = muted(new Date(e.ts).toLocaleTimeString());
        const link = button(e.data.location, () => fill(e.data.location), {
          border: '0',
          background: 'transparent',
          padding: '0',
          fontFamily: 'var(--mono)',
          textAlign: 'left',
          overflowWrap: 'anywhere',
        });
        link.title = 'Put in the box';
        li.append(at, link);
        if (e.data.error) li.append(h('span', 'no match', { color: 'var(--destructive)' }));
        list.append(li);
      }
      recent.append(list);
    };

    const drawTree = () => {
      tree.replaceChildren();
      if (!routes) return;
      const matched = new Set((current?.matches ?? []).map((m) => m.path));
      const list = h('ul', undefined, { listStyle: 'none', margin: '0', padding: '0' });
      const add = (nodes, depth) => {
        for (const node of nodes) {
          const li = h('li', undefined, { paddingLeft: `${depth * 16}px` });
          if (node.shell) {
            li.append(muted(node.shell, 'div', { padding: '3px 8px' }));
            list.append(li);
            if (node.branches) {
              node.branches.forEach((branch, i) => {
                list.append(muted(`Branch ${i}`, 'li', { padding: '3px 0', paddingLeft: `${(depth + 1) * 16 + 8}px` }));
                add(branch, depth + 2);
              });
            } else {
              add(node.routes, depth + 1);
            }
            continue;
          }
          const row = button('', () => fill(node.path), {
            border: '0',
            width: '100%',
            textAlign: 'left',
            padding: '3px 8px',
            borderRadius: '4px',
            background: matched.has(node.path) ? 'var(--selection)' : 'transparent',
            display: 'flex',
            gap: '8px',
            flexWrap: 'wrap',
            alignItems: 'baseline',
          });
          row.title = 'Put in the box';
          row.append(mono(node.path, { overflowWrap: 'anywhere' }));
          if (node.name) row.append(muted(node.name));
          if (node.redirect) row.append(muted('redirect'));
          li.append(row);
          list.append(li);
          add(node.routes, depth + 1);
        }
      };
      add(routes, 0);
      tree.append(list);
    };

    const draw = () => {
      drawCurrent();
      drawHistory();
      drawTree();
    };

    const apply = (e) => {
      if (run !== null && e.run !== run) history = [];
      run = e.run;
      history.push(e);
      if (history.length > HISTORY) history.shift();
      current = e.data;
    };

    const load = async () => {
      try {
        const state = await context.request('go_router.state');
        if (!alive) return;
        routes = state.routes;
        // The app's location wins over the last event, which may be from an earlier run.
        if (state.current) current = state.current;
        note.textContent = '';
      } catch (err) {
        if (!alive) return;
        note.textContent = fail(err);
      }
      draw();
    };

    for (const e of context.events) apply(e);
    draw();
    load();
    const stop = context.onEvents((events) => {
      for (const e of events) apply(e);
      draw();
    });
    return () => {
      alive = false;
      stop();
    };
  },
};
export const icon = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 13v8\"/><path d=\"M12 3v3\"/><path d=\"M18 6a2 2 0 0 1 1.387.56l2.307 2.22a1 1 0 0 1 0 1.44l-2.307 2.22A2 2 0 0 1 18 13H6a2 2 0 0 1-1.387-.56l-2.306-2.22a1 1 0 0 1 0-1.44l2.306-2.22A2 2 0 0 1 6 6z\"/></svg>";
''';

String _riverpod() => r'''
// The Riverpod tab: every provider with its current value and recent changes.

// What an event does to the provider it names.
function step(item, e) {
  if (e.kind === 'riverpod.add') {
    item.value = e.data.value;
    item.alive = true;
  } else if (e.kind === 'riverpod.update') {
    item.value = e.data.next;
    item.history.push(e);
  } else if (e.kind === 'riverpod.dispose') {
    item.alive = false;
  }
}

const style = (el, css) => Object.assign(el.style, css);

export default {
  api: 1,
  id: 'riverpod',
  label: 'Riverpod',
  kinds: (kind) => kind.startsWith('riverpod.'),
  renderTab(el, context) {
    const items = new Map();
    let run = null;
    let selected = null;
    let shown = null;

    const apply = (e) => {
      // A restart starts over.
      if (run !== null && e.run !== run) items.clear();
      run = e.run;
      let item = items.get(e.data.id);
      if (!item) {
        item = { id: e.data.id, name: e.data.provider, value: null, alive: true, history: [], version: 0 };
        items.set(item.id, item);
      }
      step(item, e);
      if (item.history.length > 20) item.history.shift();
      item.version++;
    };

    const list = document.createElement('ul');
    const detail = document.createElement('div');
    style(el, { display: 'flex', gap: '16px', alignItems: 'flex-start' });
    style(list, {
      listStyle: 'none',
      margin: '0',
      padding: '0 12px 0 0',
      minWidth: '200px',
      borderRight: '1px solid var(--border)',
    });
    style(detail, { flex: '1', minWidth: '0' });
    el.append(list, detail);

    const draw = () => {
      const all = [...items.values()].sort((a, b) => a.name.localeCompare(b.name));
      const twins = new Set(all.filter((a, i) => all.some((b, j) => i !== j && a.name === b.name)).map((a) => a.id));
      list.replaceChildren(
        ...all.map((item) => {
          const li = document.createElement('li');
          const button = document.createElement('button');
          button.type = 'button';
          button.textContent = twins.has(item.id) ? `${item.name} #${item.id}` : item.name;
          style(button, {
            border: '0',
            background: item.id === selected ? 'var(--selection)' : 'transparent',
            width: '100%',
            textAlign: 'left',
            padding: '4px 8px',
            borderRadius: '4px',
            cursor: 'pointer',
            opacity: item.alive ? '1' : '0.5',
          });
          button.onclick = () => {
            selected = item.id;
            draw();
          };
          li.append(button);
          return li;
        }),
      );

      const item = items.get(selected);
      // Redraw only on change, so open tree nodes stay open.
      const key = item ? `${item.id}|${item.version}` : String(items.size);
      if (key === shown) return;
      shown = key;
      detail.replaceChildren();
      if (!item) {
        detail.textContent = items.size ? 'Select a provider.' : 'No providers yet.';
        return;
      }
      const title = document.createElement('h3');
      title.textContent = item.alive ? item.name : `${item.name} (disposed)`;
      detail.append(
        title,
        context.ui.copy(() => JSON.stringify(item.value, null, 2), 'Copy value'),
        context.ui.json(item.value),
      );
      if (item.history.length) {
        const recent = document.createElement('h3');
        recent.textContent = 'Recent';
        detail.append(recent);
        for (const e of item.history.toReversed()) {
          const at = document.createElement('div');
          at.className = 'muted';
          at.textContent = `${new Date(e.ts).toLocaleTimeString()} ${e.kind.slice(9)}`;
          detail.append(at, context.ui.json(e.data.next));
        }
      }
    };

    for (const e of context.events) apply(e);
    draw();
    // The app's current values win over what events rebuilt; the next event
    // joins whatever run it belongs to.
    context.request('riverpod.state').then(
      (result) => {
        for (const p of result.providers) {
          const item = items.get(p.id);
          if (item) Object.assign(item, { value: p.value, alive: true, version: item.version + 1 });
          else items.set(p.id, { id: p.id, name: p.provider, value: p.value, alive: true, history: [], version: 0 });
        }
        run = null;
        draw();
      },
      () => {},
    );
    return context.onEvents((events) => {
      for (const e of events) apply(e);
      draw();
    });
  },
};
export const icon = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"1\"/><path d=\"M20.2 20.2c2.04-2.03.02-7.36-4.5-11.9-4.54-4.52-9.87-6.54-11.9-4.5-2.04 2.03-.02 7.36 4.5 11.9 4.54 4.52 9.87 6.54 11.9 4.5Z\"/><path d=\"M15.7 15.7c4.52-4.54 6.54-9.87 4.5-11.9-2.03-2.04-7.36-.02-11.9 4.5-4.52 4.54-6.54 9.87-4.5 11.9 2.03 2.04 7.36.02 11.9-4.5Z\"/></svg>";
''';

String _secure_storage() => r'''
// The Secure storage tab: the app's flutter_secure_storage keys, each value read only when revealed.

const style = (el, css) => Object.assign(el.style, css);

function h(tag, text, css) {
  const el = document.createElement(tag);
  if (text !== undefined) el.textContent = text;
  if (css) style(el, css);
  return el;
}

function button(text, onclick, css) {
  const b = h('button', text, css);
  b.type = 'button';
  b.onclick = onclick;
  return b;
}

function textarea(value) {
  const t = h('textarea', undefined, { width: '100%', minHeight: '64px', fontFamily: 'var(--mono)' });
  t.value = value;
  t.spellcheck = false;
  return t;
}

export default {
  api: 1,
  id: 'secure_storage',
  label: 'Secure storage',
  renderTab(el, context) {
    let alive = true;
    let keys = null;
    let filter = '';
    // Values the user revealed, by key; cleared on refresh.
    const shown = new Map();
    let editing = null;

    const search = h('input', undefined, { flex: '1', minWidth: '0' });
    search.type = 'search';
    search.placeholder = 'Filter keys';
    search.oninput = () => {
      filter = search.value.toLowerCase();
      drawTable();
    };
    const bar = h('div', undefined, { display: 'flex', gap: '8px', alignItems: 'center', marginBottom: '8px' });
    bar.append(
      search,
      button('Refresh', () => refresh()),
    );
    // Errors in note, the list's own state in status.
    const note = h('p');
    note.className = 'muted';
    const status = h('p');
    status.className = 'muted';
    const table = h('table', undefined, { width: '100%', borderCollapse: 'collapse' });
    const add = h('div', undefined, { marginTop: '12px' });
    const footer = h('p');
    footer.className = 'muted';
    el.append(bar, note, status, table, add, footer);

    const fail = (err) => {
      const message = err instanceof Error ? err.message : String(err);
      return message.includes('No handler named secure_storage.')
        ? 'The app has not called DevpulSecureStorage.install().'
        : message;
    };

    const reveal = async (key) => {
      const { value } = await context.request('secure_storage.read', { key });
      if (value === null) throw new Error(`${key} is gone. Refresh.`);
      shown.set(key, value);
    };

    // Runs a call from a row, then redraws; failures go in the note.
    const act = async (b, run) => {
      b.disabled = true;
      try {
        await run();
        note.textContent = '';
      } catch (err) {
        if (!alive) return;
        note.textContent = fail(err);
      }
      if (alive) drawTable();
    };

    // Two clicks: the first arms it for 3 s.
    const deleteButton = (key) => {
      let armed = null;
      const b = button('Delete', () => {
        if (!armed) {
          b.textContent = 'Confirm';
          b.style.color = 'var(--destructive)';
          armed = setTimeout(() => {
            armed = null;
            b.textContent = 'Delete';
            b.style.color = '';
          }, 3000);
          return;
        }
        clearTimeout(armed);
        act(b, async () => {
          await context.request('secure_storage.delete', { key });
          shown.delete(key);
          keys = keys.filter((k) => k !== key);
        });
      });
      return b;
    };

    const valueCell = (key) => {
      const cell = h('td', undefined, { padding: '4px 8px', width: '100%' });
      const actions = h('div', undefined, { display: 'flex', gap: '6px', marginTop: '4px', flexWrap: 'wrap' });
      if (editing === key) {
        const input = textarea(shown.get(key) ?? '');
        const save = button('Save', () =>
          act(save, async () => {
            await context.request('secure_storage.write', { key, value: input.value });
            shown.set(key, input.value);
            editing = null;
          }),
        );
        actions.append(
          save,
          button('Cancel', () => {
            editing = null;
            drawTable();
          }),
        );
        cell.append(input, actions);
        queueMicrotask(() => input.focus());
        return cell;
      }
      if (!shown.has(key)) {
        cell.append(h('span', '••••••••', { opacity: '0.6' }));
        const show = button('Show', () => act(show, () => reveal(key)), { marginLeft: '8px' });
        cell.append(show);
        return cell;
      }
      const value = shown.get(key);
      const pre = h('pre', value === '' ? '(empty)' : value);
      pre.className = 'code';
      actions.append(
        button('Hide', () => {
          shown.delete(key);
          drawTable();
        }),
        context.ui.copy(() => shown.get(key) ?? '', 'Copy'),
      );
      if (context.writes) {
        actions.append(
          button('Edit', () => {
            editing = key;
            drawTable();
          }),
        );
      }
      cell.append(pre, actions);
      return cell;
    };

    const drawTable = () => {
      table.replaceChildren();
      status.textContent = '';
      drawAdd();
      if (!keys) return;
      if (!keys.length) {
        status.textContent = 'No keys.';
        return;
      }
      const matching = filter ? keys.filter((k) => k.toLowerCase().includes(filter)) : keys;
      const body = h('tbody');
      for (const key of matching) {
        const row = h('tr', undefined, { borderTop: '1px solid var(--border)', verticalAlign: 'top' });
        const name = h('td', key, { padding: '4px 8px', whiteSpace: 'nowrap', fontWeight: '500' });
        row.append(name, valueCell(key));
        if (context.writes) {
          const cell = h('td', undefined, { padding: '2px 8px', textAlign: 'right' });
          cell.append(deleteButton(key));
          row.append(cell);
        }
        body.append(row);
      }
      table.append(body);
      if (!matching.length) status.textContent = 'No key matches.';
    };

    const drawAdd = () => {
      add.replaceChildren();
      footer.textContent = context.writes ? '' : 'Turn on Allow writes in the Plugins tab to add, edit and delete.';
      if (!context.writes || !keys) return;
      const key = h('input', undefined, { width: '100%', marginBottom: '6px' });
      key.placeholder = 'Key';
      const value = textarea('');
      value.placeholder = 'Value';
      const save = button('Add', () => {
        const k = key.value;
        if (!k) {
          note.textContent = 'Give a key.';
          return;
        }
        if (keys.includes(k)) {
          note.textContent = `${k} exists; edit it in the list.`;
          return;
        }
        act(save, async () => {
          await context.request('secure_storage.write', { key: k, value: value.value });
          keys = [...keys, k].sort();
          shown.set(k, value.value);
        });
      });
      add.append(h('h3', 'Add'), key, value, save);
    };

    const refresh = async () => {
      shown.clear();
      editing = null;
